local uh = mapper("ucihelper")
local sub, format, tinsert = string.sub, string.format, table.insert
local popen = io.popen
local bit = require("bit")

local sys_class_iproutes_ = {
  objectType = {
    name = "sys.class.iproutes.@.",
    access = "readOnly",
    numEntriesParameter = "RoutesNumberOfEntries",
    minEntries = 0,
    maxEntries = math.huge,
    parameters = {
            Destination = {
                access = "readOnly",
                type = "string",
            },
            Gateway = {
                access = "readOnly",
                type = "string",
            },
            Mask = {
                access = "readOnly",
                type = "string",
            },
            Source = {
                access = "readOnly",
                type = "string",
            },
            Flags = {
                access = "readOnly",
                type = "string",
            },
            Metric = {
                access = "readOnly",
                type = "string",
            },
            Iface = {
                access = "readOnly",
                type = "string",
            },
            Table = {
                access = "readOnly",
                type = "string",
            },

   }
  }
}

local function HEXIP2string(HEX)
   local D1,D2,D3,D4 = tonumber(sub(HEX, 1,2),"16"), tonumber(sub(HEX, 3,4),"16"), tonumber(sub(HEX, 5,6),"16"), tonumber(sub(HEX, 7,8),"16")
   local result = format("%s.%s.%s.%s",D1,D2,D3,D4)
   return result
end

local notallowed = {
     ["local"]       =     0,
     ["broadcast"]   =     0,
     ["unreachable"] =     0,
     ["fe80"]        =     0,
     ["ff00"]        =     0,
}

local function convertmask(x)
    local num = bit.lshift(0xffffffff, 32-x)
    local hex_num = bit.tohex(num)
    return HEXIP2string(hex_num)
end

local function findoffset(tabletest,wordtest)
    for x=1, #tabletest do
         if tabletest[x] == wordtest then
            return x
         end
    end
    return nil
end

local function generate_iptables()
   local iptables = {}
   iptables[#iptables+1] = "main"
   local binding = { config = "network", sectionname = "interface", option = "ip4table" }
   uh.foreach_on_uci(binding, function(s)
       if s["ip4table"]  then
           iptables[#iptables+1] = s["ip4table"]
       end
   end)
   return iptables
end

local function getIPIntf(x)
   local returnvar = ""
   local binding = { config = "network", sectionname = "interface", option = "ifname" }
   uh.foreach_on_uci(binding, function(s)
             if x == s["ifname"] and returnvar == "" then
               returnvar = format("%s", s[".name"])
            end

   end)
   return returnvar
end

local function generate_data(tableref)
    local entries = {}
    local datastore = {}
    local count = 1

    local readtable = popen(format("ip route show table %s 2>&1",tableref))
    for line in readtable:lines() do
          local words = {}
          for word in string.gmatch(line, "%S+") do
             words[#words+1]= word
          end
          if notallowed[words[1]]~= 0 then
            tinsert(datastore,{info = words, table = format("%s",tableref)})
            count = count+1
          end
    end
    readtable:close()
    return datastore
end

local function entriesRoutes()
    local entries = {}
    local datastore = {}

    local iptables = generate_iptables()
    for x=1, #iptables do
      local count = 1
      local readtable = popen(format("ip route show table %s 2>&1",iptables[x]))
      for line in readtable:lines() do
        -- make sure iptable exists
        if line ~= "" and string.find(line, "Error:") == nil then
            local words = {}
            for word in string.gmatch(line, "%S+") do
               words[#words+1]= word
            end
            if notallowed[words[1]]~= 0 then
              tinsert(entries, format("%s-%s",iptables[x],count))

              count = count+1
            end
        end
      end
      readtable:close()
    end
   return entries
end

local function getall(mapping, key)
    local store = {Destination = "", Gateway = "" ,Mask = "", Source="", Flags="", Metric="", Metric="", Table=""}
    local split = {}
    for word in string.gmatch(key, "%w+") do
      split[#split+1]= word
    end
    local tb = split[1]
    local idx = split[2]
    local datastore = generate_data(tb)
    local data = datastore[tonumber(idx)]

    store["Table"] = tb

    if data.info[1] ~= "default" then
        local split = {}
        for word in string.gmatch(data.info[1], "%w+") do
          split[#split+1]= word
        end
        store["Destination"] =  format("%s.%s.%s.%s",split[1],split[2],split[3],split[4])
        if  split[5] then
          store["Mask"] = convertmask(split[5])
        end
    else
       store["Destination"] = data.info[1]
    end

    local offset = findoffset(data.info, "via")
    if offset then
      store["Gateway"] = data.info[offset+1]
    end

    local offset = findoffset(data.info, "dev")
    if offset then
      store["Iface"] = getIPIntf(data.info[offset+1])
    end

    local offset = findoffset(data.info, "src")
    if offset then
      if data.info[offset+2] then
        store["Source"] = format("%s/%s",data.info[offset+1],data.info[offset+1])
      else
        store["Source"] = data.info[offset+1]
      end
    end

    local offset = findoffset(data.info, "metric")
    if offset then
      store["Metric"] =  data.info[offset+1]
    else
      store["Metric"] =  "0"
    end
    return store
end

local function get(mapping, paramName, key)
   local value = getall(mapping, key)
   return value[paramName]
end

sys_class_iproutes_.getall = getall
sys_class_iproutes_.entries = entriesRoutes
sys_class_iproutes_.get = get
register(sys_class_iproutes_)
